<script lang="ts">
	import type { PptxElementAnimation, PptxAnimationTrigger } from 'pptx-viewer-core'; import type { EditorState } from '../../../editor/editor-state.svelte'; const {editor}:{editor:EditorState}=$props(); const slide=$derived(editor.slides[editor.currentSlideIndex]); const animations=$derived([...(slide?.animations??[])].sort((a,b)=>(a.order??0)-(b.order??0)));
	function replace(index:number,patch:Partial<PptxElementAnimation>):void{if(!slide)return;const target=animations[index];if(!target)return;const next=(slide.animations??[]).map((item)=>item===target?{...item,...patch}:item);editor.commitSlides(editor.slides.map((item,i)=>i===editor.currentSlideIndex?{...item,animations:next}:item))}
	function move(index:number,delta:number):void{const other=index+delta;if(other<0||other>=animations.length)return;replace(index,{order:animations[other].order??other});replace(other,{order:animations[index].order??index})}
</script>
{#if animations.length}<div class="timeline"><h4>Animation Timeline</h4>{#each animations as animation,index}<div class:selected={animation.elementId===editor.selectedElementId}><span>{index+1}. {animation.elementId}</span><select value={animation.trigger??'onClick'} onchange={(e)=>replace(index,{trigger:e.currentTarget.value as PptxAnimationTrigger})}><option value="onClick">On click</option><option value="withPrevious">With previous</option><option value="afterPrevious">After previous</option></select><input aria-label="Duration" type="number" min="0" step="100" value={animation.durationMs??500} onchange={(e)=>replace(index,{durationMs:Number(e.currentTarget.value)})} /><input aria-label="Delay" type="number" min="0" step="100" value={animation.delayMs??0} onchange={(e)=>replace(index,{delayMs:Number(e.currentTarget.value)})} /><button disabled={index===0} onclick={()=>move(index,-1)}>↑</button><button disabled={index===animations.length-1} onclick={()=>move(index,1)}>↓</button></div>{/each}</div>{/if}
<style>.timeline{display:grid;flex-basis:100%;gap:4px;padding-top:6px;border-top:1px solid var(--pptx-border)}h4{margin:0;font-size:10px;text-transform:uppercase}.timeline>div{display:grid;grid-template-columns:minmax(120px,1fr) 110px 70px 70px 26px 26px;gap:4px;align-items:center;padding:4px;border-radius:5px;background:var(--pptx-muted);font-size:10px}.timeline>div.selected{box-shadow:inset 3px 0 var(--pptx-primary)}input,select,button{min-width:0;height:24px;border:1px solid var(--pptx-border);border-radius:4px;background:var(--pptx-background);color:inherit;font-size:10px}</style>
